const menu=document.querySelector('#menu'),menuOpen=document.querySelector('#menu-open');
function toggleMenu(open){menu.hidden=!open;menuOpen.setAttribute('aria-expanded',String(open));document.body.style.overflow=open?'hidden':'';if(open)document.querySelector('#menu-close').focus();else menuOpen.focus();}
menuOpen.onclick=()=>toggleMenu(true);document.querySelector('#menu-close').onclick=()=>toggleMenu(false);menu.querySelectorAll('a').forEach(a=>a.onclick=()=>toggleMenu(false));menu.addEventListener('keydown',e=>{if(e.key==='Escape')toggleMenu(false);if(e.key==='Tab'){const items=[...menu.querySelectorAll('button,a')],first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target);}}),{threshold:.12});document.querySelectorAll('.reveal').forEach(e=>observer.observe(e));
const detail=document.querySelector('#detail');const roles={operator:['01 / OPERATOR','让灵感有一个方向。','运营官理解账号目标，将素材、受众与要求整理成待确认的内容任务书。信息不足时提出问题，关键选择由你决定。','你将看到：目标摘要 / 待补问题 / 内容任务书'],scout:['02 / SCOUT','找到属于你的切口。','流量捕捉者研究你提供的材料，形成带依据的选题机会，说明每个方向为什么适合账号。当前组件不会自动联网抓取热点。','你将看到：机会卡 / 来源依据 / 选题理由'],director:['03 / DIRECTOR','把你的声音，写进作品。','内容导演根据确认的任务书组织叙事，输出标题、封面文案和正文；按选定范围修改，保留版本差异。','你将看到：候选图文 / 审稿意见 / 修改前后对照'],analyst:['04 / ANALYST','读懂字里行间的反应。','数据分析师将模拟观众的阅读事件对应到具体片段，解释疑问、退出与版本差异，为改稿提供线索。模拟结果不代表真实观众效果。','你将看到：逐段反应 / 诊断建议 / 比较报告']};
function showDetail(data){document.querySelector('#detail-tag').textContent=data[0];document.querySelector('#detail-title').textContent=data[1];document.querySelector('#detail-copy').textContent=data[2];document.querySelector('#detail-output').textContent=data[3];detail.showModal();}
document.querySelectorAll('[data-role]').forEach(b=>b.onclick=()=>showDetail(roles[b.dataset.role]));document.querySelector('#reel-open').onclick=()=>showDetail(['ZHONGMU / EXPERIENCE','从一个念头，到一份作品。','输入目标与素材 → 确认任务书 → 团队协作创作 → 按需模拟试映 → 选择修改 → 导出你认可的版本。','当前展示为 landing page 首版。Agent 组件与完整工作台的联调正在准备中。']);
document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close').onclick=()=>d.close();d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});});
const examples=[['“拍自然的人像，一定需要昂贵的相机吗？”','这个问题与我有关。我想继续看看，有没有今天就能试的方法。'],['“请朋友走向窗边，回头和你聊一句今天的趣事。”','我能想象这个动作。但光线不好的时候，应该怎么调整？'],['“先观察表情，再举起相机。把注意力从参数移回眼前的人。”','这给了我一个清楚的起点。我会先试一次，再考虑器材。']];document.querySelectorAll('[data-segment]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-segment]').forEach(x=>x.classList.toggle('active',x===b));let d=examples[+b.dataset.segment];document.querySelector('#segment-copy').textContent=d[0];document.querySelector('#reaction-copy').textContent=d[1];});
const brief=document.querySelector('#brief');document.querySelector('#brief-open').onclick=()=>brief.showModal();brief.querySelector('form').onsubmit=e=>{e.preventDefault();const idea=document.querySelector('#idea').value.trim(),audience=document.querySelector('#audience').value.trim();if(!idea||!audience){document.querySelector('#brief-status').textContent='请填写想法与目标读者，不能只输入空格。';return;}const text=`众幕 AI / 创作需求\n\n想法：${idea}\n目标读者：${audience}\n\n状态：本地草稿，尚未提交给 Agent。\n`;const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='zhongmu-creative-brief.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#brief-status').textContent='需求卡片已生成并下载。你的输入未上传。';};
